<?php
$sites=['studio'=>['Nexa Atelier','پروژه‌ها و درخواست‌ها'],'estate'=>['Northline Estates','فایل‌ها و درخواست‌های ملک'],'clinic'=>['Aura Clinic','رزروها و خدمات']];$d=$sites[$siteType];$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$pdo=db();if(($_POST['action']??'')==='delete'){$pdo->prepare('DELETE FROM client_demo_items WHERE id=? AND site_type=?')->execute([(int)$_POST['id'],$siteType]);$message='آیتم حذف شد.';}else{$data=[$siteType,trim($_POST['title']),trim($_POST['subtitle']),trim($_POST['image']),(int)$_POST['price'],trim($_POST['status'])];if(!empty($_POST['id'])){$pdo->prepare('UPDATE client_demo_items SET title=?,subtitle=?,image=?,price=?,status=? WHERE site_type=? AND id=?')->execute([$data[1],$data[2],$data[3],$data[4],$data[5],$data[0],(int)$_POST['id']]);$message='آیتم ویرایش شد.';}else{$pdo->prepare('INSERT INTO client_demo_items(site_type,title,subtitle,image,price,status,created_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP())')->execute($data);$message='آیتم اضافه شد.';}}}catch(Throwable $e){$message=$e->getMessage();}}
$defaultImage=$siteType==='estate'?'estate-hero.jpg':($siteType==='clinic'?'clinic-hero.jpg':'architecture-hero.jpg');$edit=null;if(!empty($_GET['edit'])){$s=db()->prepare('SELECT * FROM client_demo_items WHERE id=? AND site_type=?');$s->execute([(int)$_GET['edit'],$siteType]);$edit=$s->fetch();}$s=db()->prepare('SELECT * FROM client_demo_items WHERE site_type=? ORDER BY id DESC');$s->execute([$siteType]);$items=$s->fetchAll();$r=db()->prepare('SELECT * FROM client_demo_requests WHERE site_type=? ORDER BY id DESC');$r->execute([$siteType]);$requests=$r->fetchAll();page_header($d[0].' Dashboard','admin');
?>
