lete"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="admin-delete">حذف</button></form></div></div><?php endforeach;if(!$items):?><div class="empty">هنوز آیتمی ساخته نشده است.</div><?php endif;?></div></div></div><div class="admin-card" style="margin-top:1.5rem"><h2>درخواست‌های ورودی</h2><div class="admin-list"><?php foreach($requests as $req):?><div class="admin-row"><div><b><?=e($req['name'])?></b><span style="display:block;color:var(--muted);font-size:.65rem"><?=e($req['phone'])?> · <?=e($req['service'])?></span></div><span><?=e($req['status'])?></span></div><?php endforeach;if(!$requests):?><div class="empty">درخواستی ثبت نشده است.</div><?php endif;?></div></div></div></section>
